logi=> with recursive arriba as (
  select id, nombre, padre_id, 0 as sube from ubicaciones where nombre = 'Andén 3'
  union all
  select u.id, u.nombre, u.padre_id, a.sube + 1 from ubicaciones u join arriba a on u.id = a.padre_id
)
select sube, nombre from arriba order by sube;

logi=> with recursive r as (
  select id, padre from ciclo where id = 1
  union all
  select c.id, c.padre from ciclo c join r on c.id = r.padre
) cycle id set es_ciclo using camino
select id, padre, es_ciclo from r;
